class Server:

    VALID_INFO_KEYS = ("addr", "content")
    SEND_TYPE = "send"
    RECEIVE_TYPE = "receive"
    INVALID_INFO_STRUCTURE_MESSAGE = "info structure is not correct"

    def __init__(self):
        self._white_list = []
        self._send_struct = {}
        self._receive_struct = {}

    @property
    def white_list(self):
        return self._white_list

    @property
    def send_struct(self):
        return self._send_struct

    @property
    def receive_struct(self):
        return self._receive_struct

    def _is_valid_info(self, info):
        return isinstance(info, dict) and all(key in info for key in self.VALID_INFO_KEYS)

    def _is_address_in_white_list(self, addr):
        return addr in self._white_list

    def add_white_list(self, addr):
        if self._is_address_in_white_list(addr):
            return False
        self._white_list.append(addr)
        return self._white_list

    def del_white_list(self, addr):
        if not self._is_address_in_white_list(addr):
            return False
        self._white_list.remove(addr)
        return self._white_list

    def recv(self, info):
        if not self._is_valid_info(info):
            return -1
        addr = info["addr"]
        content = info["content"]
        if not self._is_address_in_white_list(addr):
            return False
        self._receive_struct = {"addr": addr, "content": content}
        return content

    def send(self, info):
        if not self._is_valid_info(info):
            return self.INVALID_INFO_STRUCTURE_MESSAGE
        self._send_struct = self._build_struct(info)
        return None

    def show(self, type):
        if type == self.SEND_TYPE:
            return self._send_struct
        if type == self.RECEIVE_TYPE:
            return self._receive_struct
        return False

    def _build_struct(self, info):
        return {"addr": info["addr"], "content": info["content"]}
